const TreeMountain = ({ transform, ...props }) => {
  const {
    clearHomeHoverRegion,
    homeHoverRegion,
    isHome,
    isHomeInteractive,
    setHomeHoverRegion,
  } = useHomeHover()
  const canInteractWithHomeHover = isHomeInteractive ?? isHome
  const isHoverActive =
    canInteractWithHomeHover && homeHoverRegion === SERVICES_HOVER_REGION
  const handleMouseEnter = useCallback(() => {
    if (canInteractWithHomeHover) {
      setHomeHoverRegion(SERVICES_HOVER_REGION)
    }
  }, [canInteractWithHomeHover, setHomeHoverRegion])
  const handleMouseLeave = useCallback(() => {
    if (canInteractWithHomeHover) {
      clearHomeHoverRegion()
    }
  }, [canInteractWithHomeHover, clearHomeHoverRegion])

  return (
    <g transform={transform} {...props}>
      <g id='tree-mountain__container'>
        <g id='tree-mountain__wrapper'>
          <g className='trees' id='tree-mountain'>
            <TreeMountainShape />

            <TreeMountainHitbox
              canInteractWithHomeHover={canInteractWithHomeHover}
              onMouseEnter={handleMouseEnter}
              onMouseLeave={handleMouseLeave}
            />
          </g>
        </g>
      </g>

      <g
        id='tree-mouintain-hover'
        transform={`translate(${TREE_HOVER_POSITION.x} ${TREE_HOVER_POSITION.y})`}
        pointerEvents='none'
        style={{
          opacity: isHoverActive ? 1 : 0,
          transition: 'opacity 220ms ease',
        }}
      >
        <TreeMountainHoverArtwork />
      </g>
    </g>
  )
}

export default TreeMountain
